    "reading": "读者先按目标定位一行，再横向查看负责人、截止日期和关键结果；也可纵向比较各目标的责任人和时间安排。",
    "groups": [
      "目标与关键结果共同说明要达成什么及如何衡量，应保持清晰的行对应关系。",
      "负责人与截止日期都是简短的执行信息，适合并列扫描，并应尽量完整显示。"
    ],
    "keep_intact": [
      "负责人姓名",
      "截止日期及其连字符",
      "关键结果中的数字、百分比和英文缩写"
    ],
    "may_wrap": [
      "目标名称可按中文语义自然换行，但应保持每行目标容易辨认。",
      "关键结果是较长的描述性文字，可自然换行；目标名称也可利用这些文字形成的行高。"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [100, 67, 65, 127],
      "idea": "均衡分配目标与关键结果的空间，同时让负责人和截止日期保持单行。"
    },
    {
      "name": "B",
      "widths": [85, 67, 65, 142],
      "idea": "优先加宽关键结果，利用其形成的行高容纳目标名称换行，方便阅读较长的衡量描述。"
    },
    {
      "name": "C",
      "widths": [129, 67, 65, 98],
      "idea": "优先完整呈现目标名称，便于纵向定位和比较目标，关键结果则在较窄列中分行阅读。"
    }
  ]
}
